    "sr-b01-u28-16": ["schedule", 0, "A2", 3, "/ˈʃɛdjuːl/", "A schedule is a plan that tells you when to do things.", "lịch trình", "What is your class schedule for today?", "schedule", ["class schedule"]],
    "sr-b01-u28-17": ["share", 1, "A1", 3, "/ʃɛː/", "To share something is to give some of it to another person.", "chia sẻ", "Jimmy shared his apple with me.", "shared", []],
    "sr-b01-u28-18": ["stage", 0, "A2", 3, "/steɪdʒ/", "A stage is a place where actors or musicians act or sing.", "sân khấu", "A large screen was on the stage.", "stage", []],
    "sr-b01-u28-19": ["storm", 0, "A2", 3, "/stɔːm/", "A storm is very bad weather. There is a lot of rain or snow.", "cơn bão", "Did that storm wake you up last night?", "storm", []],
    "sr-b01-u28-20": ["within", 4, "B1", 3, "/wɪðˈɪn/", "You use within to say that something is inside another thing.", "bên trong", "Within the box, there was a pizza.", "Within", ["within the box"]],
    "sr-b01-u29-01": ["advertise", 1, "A2", 3, "/ˈadvətʌɪz/", "To advertise is to tell people about something on TV, radio, etc.", "quảng cáo", "They used a rabbit to help them advertise their product.", "advertise", ["advertise a product"]],
    "sr-b01-u29-02": ["assign", 1, "B2", 9, "/əˈsʌɪn/", "To assign something to someone is to tell them to do it.", "giao việc, phân công", "I assigned the worker an important task.", "assigned", []],
    "sr-b01-u29-03": ["audience", 0, "A2", 3, "/ˈɔːdɪəns/", "An audience is a group of people who watch something together.", "khán giả", "There was a large audience at the game.", "audience", ["large audience"]],
    "sr-b01-u29-04": ["breakfast", 0, "A1", 3, "/ˈbrɛkfəst/", "Breakfast is the first meal of the day.", "bữa ăn sáng", "I eat breakfast at 8:00 every morning.", "breakfast", ["eat breakfast"]],
    "sr-b01-u29-05": ["competition", 0, "A2", 3, "/kɒmpɪˈtɪʃən/", "A competition is a contest to see who is the best at something.", "cuộc thi đấu", "He won the running competition over the weekend.", "competition", ["running competition"]],
    "sr-b01-u29-06": ["cool", 2, "A1", 3, "/kuːl/", "If the weather is cool, it is a little bit cold.", "mát mẻ", "The weather is cool in the fall.", "cool", []],
    "sr-b01-u29-07": ["gain", 1, "B1", 3, "/ɡeɪn/", "If you gain something, you get more of it.", "đạt được", "I gained some weight over the summer.", "gained", []],
    "sr-b01-u29-08": ["importance", 0, "B1", 3, "/ɪmˈpɔːtəns/", "Importance means the quality or condition of being needed or valued.", "tầm quan trọng", "VIPs are people of great importance.", "importance", ["great importance"]],
    "sr-b01-u29-09": ["knowledge", 0, "A2", 3, "/ˈnɒlɪdʒ/", "Knowledge is information that you have about something.", "kiến thức", "A music teacher should have good knowledge of music.", "knowledge", ["good knowledge", "knowledge of music"]],
    "sr-b01-u29-10": ["major", 2, "A2", 3, "/ˈmeɪdʒə/", "If something is major, it is big or important.", "lớn, quan trọng", "I have a major problem. My boss wants me to redo my project!", "major", ["major problem"]],
    "sr-b01-u29-11": ["mean", 2, "A1", 3, "/miːn/", "Mean describes someone who is unkind or cruel.", "xấu tính, cay nghiệt", "My co-worker is a very mean person. He gets angry very quickly.", "mean", ["mean person"]],
    "sr-b01-u29-12": ["prefer", 1, "A1", 3, "/prɪˈfɜː/", "If you prefer something, you want it more than something else.", "thích hơn", "I prefer to take the path that will lead me to a bright future.", "prefer", ["prefer to take"]],
    "sr-b01-u29-13": ["president", 0, "A2", 3, "/ˈprɛzɪdənt/", "A president is the leader of a country.", "tổng thống", "The president of our country made an important announcement.", "president", []],
    "sr-b01-u29-14": ["progress", 0, "A2", 3, "/prəˈɡrɛs/", "Progress is the act of getting closer to doing or finishing something.", "tiến bộ", "Our company made financial progress this year.", "progress", ["financial progress"]],
    "sr-b01-u29-15": ["respect", 0, "B1", 3, "/rɪˈspɛkt/", "Respect is a good opinion of someone because they are good.", "tôn trọng", "I have great respect for firemen.", "respect", ["great respect", "respect for firemen"]],
    "sr-b01-u29-16": ["rich", 2, "A1", 3, "/rɪtʃ/", "If you are rich, you have a lot of money.", "giàu có", "He’s rich. He can buy anything he wants.", "rich", []],
    "sr-b01-u29-17": ["skill", 0, "A1", 3, "/skɪl/", "A skill is the knowledge and ability that allows you to do something well.", "kỹ năng", "A snowboarder must have the right skills to do well.", "skills", []],
    "sr-b01-u29-18": ["somehow", 3, "B1", 3, "/ˈsʌmhaʊ/", "Somehow means in a way or by some means which is not known.", "bằng cách nào đó", "He somehow had to find a way to reach the life preserver.", "somehow", []],
    "sr-b01-u29-19": ["strength", 0, "B1", 3, "/strɛŋkθ/", "Strength is the physical power that you have.", "sức mạnh", "Exercising will increase your strength and give you more power.", "strength", ["increase a strength"]],
    "sr-b01-u29-20": ["vote", 1, "B1", 3, "/vəʊt/", "To vote is to officially choose between two or more things.", "bỏ phiếu", "I voted for Billy to be our class president.", "voted", []],
    "sr-b01-u30-01": ["above", 4, "A1", 3, "/əˈbʌv/", "If something is above, it is at a higher level than something else.", "ở trên", "He straightened the sign that was above the crowd.", "above", ["above the crowd"]],
    "sr-b01-u30-02": ["ahead", 3, "B1", 3, "/əˈhɛd/", "If something is ahead of something else, it is in front of it.", "phía trước", "The blue car drove on ahead of us.", "ahead", []],
