    "sr-b01-u30-04": ["belief", 0, "B1", 3, "/bɪˈliːf/", "A belief is a strong feeling that something is correct or true.", "niềm tin", "A preacher or priest should have a strong belief in God.", "belief", ["strong belief"]],
    "sr-b01-u30-05": ["center", 0, "A1", 3, "/ˈsɛntə/", "The center of something is the middle of it.", "trung tâm", "The center of a dart board is the most important spot.", "center", []],
