    "sr-b01-u30-07": ["cost", 1, "A1", 3, "/kɒst/", "To cost is to require expenditure or payment.", "có giá, tốn", "These designer shoes cost more than the regular ones.", "cost", []],
    "sr-b01-u30-08": ["demonstrate", 1, "B1", 3, "/ˈdɛmənstreɪt/", "To demonstrate something is to show how it is done.", "trình diễn, hướng dẫn cách làm", "She demonstrated her plan to her co-workers.", "demonstrated", []],
    "sr-b01-u30-09": ["different", 2, "A1", 3, "/ˈdɪfərənt/", "Different describes someone or something that is not the same as others.", "khác nhau", "Each of my sisters has a different hair style from one another.", "different", ["different hair"]],
    "sr-b01-u30-10": ["evidence", 0, "A2", 3, "/ˈɛvɪdəns/", "Evidence is a fact or thing that you use to prove something.", "bằng chứng", "He used the pictures as evidence that UFOs are real.", "evidence", []],
    "sr-b01-u30-11": ["honesty", 0, "B2", 9, "/ˈɒnɪsti/", "the quality of being truthful, sincere, and free from deceit", "trung thực", "A courtroom should be a place of honesty.", "honesty", []],
    "sr-b01-u30-12": ["idiom", 0, "A2", 9, "/ˈɪdɪəm/", "An idiom is a phrase with a meaning different from its words.", "thành ngữ", "The idiom “when pigs fly” means that something will never happen.", "idiom", []],
    "sr-b01-u30-13": ["independent", 2, "A2", 3, "/ɪndɪˈpɛndənt/", "If something is independent, it is not controlled by something else.", "độc lập", "She chose to live an independent life in the country.", "independent", ["independent life"]],
    "sr-b01-u30-14": ["inside", 0, "A2", 3, "/ɪnˈsʌɪd/", "the interior part or space within a container, room, or object", "bên trong", "The inside of the box was empty.", "inside", ["inside of the box"]],
    "sr-b01-u30-15": ["master", 0, "B1", 3, "/ˈmɑːstə/", "A master is a person who is very good at something.", "bậc thầy", "My brother is a master of taekwondo.", "master", ["master of taekwondo"]],
