    "sr-b02-u01-08": ["landscape", 0, "B1", 4, "/ˈlænskeɪp/", "A landscape is how an area of land looks.", "phong cảnh", "The landscape of the country is very green.", "landscape", ["landscape of the country"]],
    "sr-b02-u01-09": ["lift", 1, "A2", 4, "/lɪft/", "To lift something is to move it higher.", "nâng", "The man tried to lift the box.", "lift", ["lift the box"]],
    "sr-b02-u01-10": ["load", 1, "B1", 4, "/loʊd/", "To load is to put objects into something.", "chất hàng, xếp đồ vào", "The man loaded the boxes into a truck.", "loaded", []],
    "sr-b02-u01-11": ["lung", 0, "B1", 4, "/lʌŋ/", "A lung is the organ in the body that fills with air when breathing.", "phổi", "Having strong lungs is necessary for a healthy life.", "lungs", ["strong lungs"]],
    "sr-b02-u01-12": ["motion", 0, "B1", 4, "/ˈməʊʃən/", "A motion is a movement that someone makes.", "chuyển động", "The police officer made a motion with his hand.", "motion", []],
