    "sr-b02-u02-02": ["castle", 0, "A2", 4, "/ˈkæːsl/", "A castle is a building with strong walls where royalty usually lives.", "lâu đài", "The castle was built many years ago.", "castle", []],
    "sr-b02-u02-03": ["command", 1, "B1", 4, "/kəˈmænd/", "To command someone is to tell them to do something.", "ra lệnh", "The general commanded his army to attack.", "commanded", []],
    "sr-b02-u02-04": ["counsel", 1, "B2", 10, "/ˈkaʊnsəl/", "To counsel someone is to listen and give advice about a problem.", "khuyên bảo, tư vấn", "The teacher counseled the girl about her troubles.", "counseled", []],
    "sr-b02-u02-05": ["ensure", 1, "B1", 4, "/ɪnˈʃʊər/", "To ensure is to make certain that something happens.", "đảm bảo", "Eating good food ensures that we stay healthy.", "ensures", []],
