    "sr-b02-u02-07": ["jewelry", 0, "A2", 4, "/ˈdʒuːəlri/", "Jewelry is something that people wear like earrings or necklaces.", "đồ trang sức", "The woman looked beautiful with her nice dress and jewelry.", "jewelry", []],
    "sr-b02-u02-08": ["land", 1, "A1", 4, "/lænd/", "To land means to come to the ground usually from a ship or aircraft.", "hạ cánh", "The parachutist landed safely on the ground.", "landed", ["land safely"]],
    "sr-b02-u02-09": ["meteor", 0, "B1", 10, "/ˈmiːtɪər/", "A meteor is a rock from outer space that falls to Earth.", "sao băng", "We saw a meteor in the sky last night.", "meteor", []],
    "sr-b02-u02-10": ["monster", 0, "B1", 4, "/ˈmɒnstər/", "A monster is any imaginary frightening creature that looks strange.", "quái vật", "The monster scared everyone in the village.", "monster", []],
