    "sr-b02-u02-12": ["remote", 2, "B1", 4, "/rɪˈmoʊt/", "If something is remote, it is very far away and difficult to get to.", "xa xôi, hẻo lánh", "It took many days to get to the remote island.", "remote", ["remote island"]],
    "sr-b02-u02-13": ["southern", 2, "B1", 4, "/ˈsʌðərn/", "situated in, facing, or coming from the compass direction opposite the north", "miền nam", "Taegu is located in the southern part of the Korean peninsula.", "southern", ["southern part"]],
    "sr-b02-u02-14": ["statue", 0, "B1", 4, "/ˈstætjuː/", "A statue is an image of a person or animal made of stone or metal.", "bức tượng", "I saw a beautiful statue of a lion today.", "statue", ["beautiful statue", "statue of a lion"]],
    "sr-b02-u02-15": ["steam", 0, "B1", 4, "/stiːm/", "Steam is water that has become hot and has turned into a misty gas.", "hơi nước", "We could see the steam rise from the boiling water.", "steam", []],
    "sr-b02-u02-16": ["submit", 1, "B1", 4, "/səbˈmɪt/", "To submit to someone is to agree to do what they tell you to do.", "khuất phục, vâng lời", "She submitted to her mother’s wishes and did her homework.", "submitted", []],
    "sr-b02-u02-17": ["temple", 0, "B1", 4, "/ˈtempl/", "A temple is a building that is used for religious purposes.", "ngôi đền", "The people visited the temple to pray.", "temple", ["visited the temple"]],
    "sr-b02-u02-18": ["upper", 2, "B1", 4, "/ˈʌpər/", "Upper means higher in position or place.", "phía trên", "A home’s attic is at the upper part of the structure.", "upper", ["upper part"]],
    "sr-b02-u02-19": ["weed", 0, "B1", 4, "/wiːd/", "A weed is a plant, especially one that is not useful or wanted.", "cỏ dại", "The yard of the house was full of ugly weeds.", "weeds", ["ugly weeds"]],
    "sr-b02-u02-20": ["wing", 0, "B1", 4, "/wɪŋ/", "A wing is the part of an animal that lets it fly.", "cánh", "The bird used its wings to fly across the water.", "wings", []],
    "sr-b02-u03-01": ["arrow", 0, "B2", 10, "/ˈærəʊ/", "An arrow is a thin, straight stick shot from a bow.", "mũi tên", "The arrow flew through the air and hit the target.", "arrow", []],
    "sr-b02-u03-02": ["battle", 0, "B1", 4, "/ˈbætl/", "A battle is a fight between two armies during a war.", "trận chiến", "The battle lasted for many days.", "battle", []],
    "sr-b02-u03-03": ["bow", 0, "B1", 4, "/bəʊ/", "A bow is a weapon made of curved wood and string that shoots arrows.", "cây cung", "He went hunting with a bow and arrow.", "bow", []],
    "sr-b02-u03-04": ["brave", 2, "B1", 4, "/breɪv/", "When people are brave, they are not afraid to face pain or danger.", "dũng cảm", "The brave firefighter saved the girl from the burning building.", "brave", ["brave firefighter"]],
    "sr-b02-u03-05": ["chief", 0, "B1", 4, "/tʃiːf/", "A chief is the leader of a group of people.", "người đứng đầu", "The chief led the people through the mountains.", "chief", []],
    "sr-b02-u03-06": ["disadvantage", 0, "B1", 4, "/ˌdɪsədˈvæntɪdʒ/", "A disadvantage is a situation where someone is likely to lose.", "bất lợi", "Mike had a disadvantage in the race since he hurt his knee.", "disadvantage", []],
    "sr-b02-u03-07": ["enemy", 0, "B1", 4, "/ˈɛnəmɪ/", "An enemy is a country that is fighting another country during a war.", "kẻ thù", "The enemy prepared to attack the kingdom.", "enemy", []],
