    "sr-b02-u03-09": ["hardly", 3, "B1", 4, "/ˈhɑːrdlɪ/", "If something hardly happens, it almost does not happen at all.", "hầu như không", "I hardly saw the concert since I had to leave early.", "hardly", ["hardly saw"]],
    "sr-b02-u03-10": ["intend", 1, "B1", 4, "/ɪnˈtend/", "To intend to do something means to plan to do it.", "có ý định", "I intend to finish college in three years.", "intend", ["intend to finish"]],
    "sr-b02-u03-11": ["laughter", 0, "A2", 4, "/ˈlæftər/", "the happy sound people make with their voices when something is funny", "tiếng cười", "Susan’s joke made her classmates burst into laughter.", "laughter", []],
    "sr-b02-u03-12": ["log", 0, "B1", 4, "/lɒg/", "A log is a thick piece of wood that is cut from a tree.", "khúc gỗ", "The fire was too small, so we added another log to it.", "log", []],
    "sr-b02-u03-13": ["military", 0, "B1", 4, "/ˈmɪlɪtərɪ/", "The military is the armed forces of a country.", "quân đội", "I joined the military after I finished high school.", "military", ["joined the military"]],
    "sr-b02-u03-14": ["obey", 1, "B1", 4, "/oʊˈbeɪ/", "To obey means to follow what a law or a person says you must do.", "tuân theo", "My little sister did not obey my mother. Now she is in trouble.", "obey", []],
