    "sr-b05-u07-14": ["prominent", 2, "B2", 13, "/ˈprɒmənənt/", "When something is prominent, it is important and well known.", "nổi bật", "Queen Victoria was a prominent person in history.", "prominent", ["prominent person"]],
    "sr-b05-u07-15": ["repetitive", 2, "C1", 13, "/riˈpetətiv/", "involving the same action again and again until it feels monotonous", "lặp đi lặp lại", "Working on an assembly line making cars every day is a repetitive job.", "repetitive", ["repetitive job"]],
    "sr-b05-u07-16": ["reproductive", 2, "B2", 13, "/riːprəˈdʌktiv/", "If something is reproductive, it has to do with a living thing producing young.", "sinh sản", "The reproductive system of a plant is simple.", "reproductive", ["reproductive system"]],
    "sr-b05-u07-17": ["temperate", 2, "B2", 13, "/ˈtempərit/", "When a place is temperate, it never gets too hot or cold.", "ôn đới", "In Peru, the weather is temperate and rarely gets too hot or cold.", "temperate", []],
    "sr-b05-u07-18": ["tolerance", 0, "B2", 13, "/ˈtɒlərəns/", "Tolerance is the ability to accept something painful or unpleasant.", "sức chịu đựng, sự khoan dung", "Boxers have a high tolerance for pain.", "tolerance", ["high tolerance", "tolerance for pain"]],
    "sr-b05-u07-19": ["undergo", 1, "B2", 13, "/ˈʌndərˈgoʊ/", "To undergo an action means to have it happen to you.", "trải qua", "The cancer patient undergoes treatments twice a week. gous", "undergoes", ["undergo treatments"]],
    "sr-b05-u07-20": ["vulnerable", 2, "B2", 13, "/ˈvʌlnərəbəl/", "When someone is vulnerable, they are weak and without protection.", "dễ bị tổn thương", "He felt very vulnerable when he was stranded in the desert.", "vulnerable", []],
    "sr-b05-u08-01": ["adept", 2, "C1", 13, "/əˈdept/", "If someone is adept at something, they are very good at doing it.", "lão luyện", "The carpenter is very adept at building houses.", "adept", ["adept at building"]],
    "sr-b05-u08-02": ["barren", 2, "B2", 13, "/ˈbærən/", "If land is barren, it has no plants growing on it.", "cằn cỗi", "People cannot farm in barren lands.", "barren", ["barren lands"]],
    "sr-b05-u08-03": ["ceramic", 2, "B2", 13, "/səˈræmik/", "If something is ceramic, it is made of baked clay.", "gốm sứ", "The house’s roof was made of ceramic tiles.", "ceramic", ["ceramic tiles"]],
    "sr-b05-u08-04": ["culinary", 2, "B2", 13, "/ˈkʌləneri/", "If something is culinary, it is related to cooking.", "ẩm thực", "I gained culinary skills after working in a restaurant for many years.", "culinary", ["culinary skills"]],
    "sr-b05-u08-05": ["dense", 2, "B2", 13, "/dens/", "If something is dense, it has a lot of things close together.", "dày đặc", "I easily became lost in the dense forest.", "dense", ["dense forest"]],
    "sr-b05-u08-06": ["dignity", 0, "B2", 13, "/ˈdignəti/", "Dignity is the ability to be calm and worthy of respect.", "phẩm giá", "When his company went out of business, he faced it with dignity.", "dignity", []],
    "sr-b05-u08-07": ["dominate", 1, "B1", 7, "/ˈdɒməneɪt/", "To dominate someone or something is to control them.", "thống trị", "The loud man dominated the conversation.", "dominated", ["dominate the conversation"]],
    "sr-b05-u08-08": ["edible", 2, "C1", 13, "/ˈedəbəl/", "If something is edible, you can eat it.", "ăn được", "We learn about edible plants when we go camping.", "edible", ["edible plants"]],
