    "sr-b05-u08-10": ["intake", 0, "B2", 13, "/ˈinteɪk/", "the total quantity of food, drink, or air consumed by the body", "lượng tiêu thụ", "The doctor said I needed to increase my intake of fruits and vegetables.", "intake", ["increase an intake"]],
    "sr-b05-u08-11": ["likewise", 3, "B1", 7, "/ˈlaɪkwaɪz/", "If someone does something likewise, they do the same thing as someone else.", "tương tự như vậy", "If Joe is staying away from school to go swimming, I want to do likewise.", "likewise", []],
    "sr-b05-u08-12": ["malnutrition", 0, "C1", 13, "/mælnjuˈtriʃən/", "Malnutrition is the condition of not getting enough nutrients.", "suy dinh dưỡng", "After eating only a meager amount of food, she suffered from malnutrition.", "malnutrition", []],
    "sr-b05-u08-13": ["medication", 0, "B1", 7, "/ˌmedəˈkeɪʃən/", "a pharmaceutical drug or remedy prescribed to treat or relieve illness", "thuốc men", "The doctor gave me medication to treat my illness.", "medication", []],
    "sr-b05-u08-14": ["misconception", 0, "B2", 13, "/miskənˈsepʃən/", "A misconception is a wrong idea about something.", "quan niệm sai lầm", "People once believed the misconception that the Earth is flat.", "misconception", ["believed the misconception"]],
    "sr-b05-u08-15": ["obscure", 2, "B2", 13, "/əbˈskjuər/", "If something is obscure, it is not well-known.", "ít được biết đến", "The old man travels the world in search of obscure books.", "obscure", ["obscure books"]],
    "sr-b05-u08-16": ["oppress", 1, "C1", 13, "/əˈpres/", "To oppress someone means to rule over them in a cruel and unfair way.", "đàn áp", "Free speech had been oppressed in his country.", "oppressed", []],
    "sr-b05-u08-17": ["peel", 1, "B1", 7, "/piːl/", "To peel fruits and vegetables is to remove their skin.", "bóc vỏ", "We peeled the apple before eating it.", "peeled", ["peel the apple before"]],
    "sr-b05-u08-18": ["prescription", 0, "B1", 7, "/priˈskripʃən/", "A prescription is permission from a doctor to get medicine.", "toa thuốc", "The doctor gave me a prescription for my medication.", "prescription", []],
    "sr-b05-u08-19": ["respirator", 0, "B2", 13, "/respəˈreɪtər/", "A respirator is a machine that helps weak or sick people breathe.", "máy trợ thở", "The man needed a respirator to breathe.", "respirator", []],
    "sr-b05-u08-20": ["strive", 1, "B2", 13, "/straɪv/", "To strive is to struggle to achieve something.", "phấn đấu", "People who strive to succeed often do.", "strive", ["strive to succeed"]],
    "sr-b05-u09-01": ["archaic", 2, "C1", 13, "/ɑːrˈkeɪk/", "If something is archaic, it is very old or outdated.", "cổ xưa", "To be competitive, we must update our archaic equipment.", "archaic", ["archaic equipment"]],
    "sr-b05-u09-02": ["benevolent", 2, "C1", 13, "/bəˈnevələnt/", "If someone is benevolent, they are kind and generous.", "nhân từ", "My father was a benevolent man and gave lots of money to charity.", "benevolent", ["benevolent man"]],
    "sr-b05-u09-03": ["brass", 0, "B2", 13, "/bræs/", "Brass is a metal that is used to make musical instruments and ornaments.", "đồng thau", "Brass is used to make musical instruments like trumpets.", "Brass", []],
    "sr-b05-u09-04": ["capitalism", 0, "B2", 13, "/ˈkæpitəlizəm/", "Capitalism is an economic system where private companies make goods for profit.", "chủ nghĩa tư bản", "Most industries in the world today are based on capitalism.", "capitalism", []],
    "sr-b05-u09-05": ["component", 0, "B2", 13, "/kəmˈpoʊnənt/", "A component is a part of a larger machine.", "thành phần", "Computers have many different components, so they are complicated to build.", "components", ["different components"]],
    "sr-b05-u09-06": ["dependence", 0, "B2", 13, "/diˈpendəns/", "Dependence is a situation in which somebody relies on something else.", "sự phụ thuộc", "Young children have a dependence on their parents.", "dependence", []],
