    "sr-b05-u09-08": ["drawback", 0, "B2", 13, "/ˈdrɔːbæk/", "A drawback is a disadvantage.", "nhược điểm", "The drawback of having a car is that it is very expensive to maintain.", "drawback", []],
    "sr-b05-u09-09": ["fad", 0, "B2", 13, "/fæd/", "A fad is something that is popular for a short time.", "mốt nhất thời", "The hula hoop was a fad for a few years, but it soon lost its popularity.", "fad", []],
