    "sr-b05-u09-11": ["managerial", 2, "B2", 13, "/ˌmænəˈdʒiəriəl/", "relating to the duties or skills of directing a team, department, or business", "thuộc về quản lý", "Nancy has a managerial position at the bank.", "managerial", ["managerial position"]],
    "sr-b05-u09-12": ["medieval", 2, "B2", 13, "/miːdiˈiːvəl/", "If something is medieval, it comes from the period between 650 and 1500 CE.", "thời trung cổ", "We visited a castle that was built during medieval times.", "medieval", ["medieval times"]],
    "sr-b05-u09-13": ["obsolete", 2, "B2", 13, "/ˈɒbsəliːt/", "If something is obsolete, it is not used anymore because something better exists.", "lỗi thời", "Since computers became inexpensive, typewriters have become obsolete.", "obsolete", []],
    "sr-b05-u09-14": ["peninsula", 0, "B2", 13, "/pəˈninsələ/", "A peninsula is a large piece of land that is surrounded by the sea on three sides.", "bán đảo", "The state of Florida is an example of a peninsula.", "peninsula", []],
    "sr-b05-u09-15": ["prestige", 0, "C1", 13, "/presˈtiːrdʒ/", "If a person has prestige, people admire or respect them.", "uy tín", "The young actress gained much prestige after she won an award.", "prestige", []],
    "sr-b05-u09-16": ["proportion", 0, "B2", 13, "/prəˈpɔːrʃən/", "A proportion is an amount that shows the link between the parts and the whole.", "tỷ lệ", "Only a small proportion of the people in this town actually work here.", "proportion", ["small proportion", "proportion of the people"]],
    "sr-b05-u09-17": ["radical", 2, "B2", 13, "/ˈrædikəl/", "If something is radical, it is very new or different.", "cấp tiến", "The president is planning to make some radical changes to the law.", "radical", ["radical changes"]],
    "sr-b05-u09-18": ["refute", 1, "B2", 13, "/riˈfjuːt/", "To refute something means to prove that it is false or incorrect.", "bác bỏ", "The bank manager has refuted the claims that he lied to his customers.", "refuted", []],
    "sr-b05-u09-19": ["spectacular", 2, "B2", 13, "/spekˈtækjələr/", "If something is spectacular, it looks or sounds very impressive.", "ngoạn mục", "There was a spectacular fireworks display in the park at New Year.", "spectacular", ["spectacular fireworks"]],
    "sr-b05-u09-20": ["weave", 1, "B1", 7, "/wiːv/", "To weave means to make cloth using horizontal and vertical threads.", "dệt", "We saw a woman weave a blanket on our vacation to South America.", "weave", []],
    "sr-b05-u10-01": ["accountant", 0, "B2", 13, "/əˈkaʊntənt/", "a professional who prepares, audits, and maintains financial records and taxes", "nhân viên kế toán", "The accountant helped me keep track of my money.", "accountant", []],
    "sr-b05-u10-02": ["capitalist", 0, "B2", 13, "/ˈkæpitəlist/", "A capitalist is a business person who invests in trade and industry for profit.", "nhà tư bản", "The capitalist invested in a factory that made wheat into cereal.", "capitalist", []],
    "sr-b05-u10-03": ["contempt", 0, "B2", 13, "/kənˈtempt/", "Contempt is the feeling of having no respect for something.", "khinh miệt", "The judge had contempt for the wicked criminal.", "contempt", []],
    "sr-b05-u10-04": ["dedicate", 1, "C1", 13, "/ˈdedikeɪt/", "To dedicate oneself to something means to put a lot of time and effort into it.", "cống hiến", "The nun dedicated herself to helping people in need.", "dedicated", ["dedicate herself"]],
    "sr-b05-u10-05": ["ditch", 0, "B1", 7, "/ditʃ/", "A ditch is a narrow hole cut into the ground by a road or a field.", "mương", "When the car slid off of the road, it fell into the ditch.", "ditch", []],
    "sr-b05-u10-06": ["enterprise", 0, "B2", 13, "/ˈentərpraɪz/", "An enterprise is a company or business.", "doanh nghiệp", "My father owns an advertising enterprise.", "enterprise", ["advertising enterprise"]],
    "sr-b05-u10-07": ["exquisite", 2, "C1", 13, "/iksˈkwizit/", "When something is exquisite, it is very beautiful or pleasant.", "tinh tế", "The artist made exquisite watercolor paintings.", "exquisite", ["exquisite watercolor"]],
    "sr-b05-u10-08": ["finance", 1, "B1", 7, "/fiˈnæns/", "To finance someone or something means to provide money for them.", "tài trợ, cấp vốn", "The government financed the scientist’s experiments with new weapons.", "financed", []],
    "sr-b05-u10-09": ["indifferent", 2, "B2", 13, "/inˈdəfrənt/", "When someone is indifferent toward something, they have a lack of interest in it.", "thờ ơ", "Lisa is indifferent toward school. She doesn’t care what her final grades are.", "indifferent", []],
