    "sr-b05-u28-03": ["autobiography", 0, "C1", 13, "/ˌɔːtəbaɪˈɒgrəfi/", "An autobiography is a true story of a person’s life written by that person.", "tự truyện", "I read an autobiography about my favorite entertainer.", "autobiography", ["read an autobiography"]],
    "sr-b05-u28-04": ["convention", 0, "B2", 13, "/kənˈvenʃən/", "A convention is behavior that is considered to be common or polite.", "quy ước", "In the US, a popular convention is to shake hands when you meet someone.", "convention", ["popular convention"]],
