    "sr-b05-u28-11": ["naughty", 2, "C1", 13, "/ˈnɔːti/", "When children are naughty, they behave badly or do not do what they are told.", "nghịch ngợm", "The boy had to go to his room because he was being naughty.", "naughty", []],
    "sr-b05-u28-12": ["norm", 0, "B1", 7, "/nɔːrm/", "an accepted standard or customary way of behaving within a society", "chuẩn mực", "Wearing a heavy coat all summer is not considered a norm in the desert.", "norm", ["considered a norm"]],
    "sr-b05-u28-13": ["orangutan", 0, "C1", 13, "/ɔːˈræŋuˈtæn/", "An orangutan is a large ape with red and brown hair and long arms.", "đười ươi", "Orangutans use their long arms to swing from trees.", "Orangutans", []],
