    "sr-b05-u28-15": ["philanthropy", 0, "C1", 13, "/fiˈlænθrəpi/", "Philanthropy is the act of helping others, without wanting anything in return.", "lòng từ thiện", "The wealthy business owner is well known for his acts of philanthropy.", "philanthropy", []],
