    "sr-b05-u29-06": ["diplomat", 0, "B2", 13, "/ˈdipləmæt/", "A diplomat is a representative of a country who works with another country.", "nhà ngoại giao", "The Spanish diplomat discussed trade issues with officials in Peru.", "diplomat", []],
