    "sr-b06-u09-01": ["artery", 0, "B2", 14, "/ˈɑːrtəri/", "An artery is a tube that takes blood from the heart to the rest of the body.", "động mạch", "Eating healthily keeps your arteries clean, so blood can flow with ease.", "arteries", ["keeps arteries"]],
    "sr-b06-u09-02": ["deterioration", 0, "B2", 14, "/diˌtiəriəˈreɪʃən/", "Deterioration is the act of becoming worse.", "sự xuống cấp", "The lack of care led to the deterioration of the house.", "deterioration", ["deterioration of the house"]],
    "sr-b06-u09-03": ["elusive", 2, "C1", 14, "/iˈluːsiv/", "If something or someone is elusive, they are hard to find.", "khó nắm bắt", "The elusive fish only came out at night.", "elusive", ["elusive fish"]],
    "sr-b06-u09-04": ["forage", 1, "B2", 14, "/ˈfɔːridʒ/", "To forage means to look around for food.", "kiếm ăn, lùng tìm thức ăn", "Many animals hide food in the fall since little can be foraged in winter.", "foraged", ["forage in winter"]],
    "sr-b06-u09-05": ["impede", 1, "B2", 14, "/imˈpiːd/", "To impede something means to keep it from moving or going forward.", "cản trở", "The barrier impeded our ability to get closer to the building.", "impeded", []],
    "sr-b06-u09-06": ["induce", 1, "B2", 14, "/inˈdjuːs/", "To induce something means to make it happen.", "gây ra, thúc đẩy xảy ra", "Running without good shoes may induce leg pain.", "induce", ["induce leg"]],
    "sr-b06-u09-07": ["inseparable", 2, "C1", 14, "/inˈsepərəbəl/", "always together and unable to be parted from one another", "không thể tách rời", "Denise and Diana have been inseparable since they first met.", "inseparable", []],
    "sr-b06-u09-08": ["invalid", 2, "C1", 14, "/ˈinvælid/", "If something is invalid, it is not correct.", "không hợp lệ", "The way to winning debates is to avoid invalid arguments.", "invalid", ["invalid arguments"]],
    "sr-b06-u09-09": ["magnify", 1, "B2", 14, "/ˈmægnəfaɪ/", "To magnify something means to make it look bigger than it really is.", "phóng đại", "Astronomers use telescopes to magnify far-away stars.", "magnify", []],
    "sr-b06-u09-10": ["mainstream", 0, "B2", 14, "/ˈmeɪnstriːm/", "The mainstream is a group of ideas that are considered normal and accepted.", "xu hướng chủ đạo", "Before punk rock music became part of the mainstream, only a few people liked it.", "mainstream", []],
    "sr-b06-u09-11": ["microbe", 0, "B2", 14, "/ˈmaɪkroʊb/", "A microbe is a very small living thing that often makes people sick.", "vi sinh vật", "The first step in curing a disease is finding the microbe that causes the disease.", "microbe", ["finding the microbe"]],
    "sr-b06-u09-12": ["negligible", 2, "B2", 14, "/ˈneglidʒəbəl/", "If something is negligible, it is extremely small and not important.", "không đáng kể", "The amount she owed was negligible. It was less than ten cents.", "negligible", []],
    "sr-b06-u09-13": ["paralysis", 0, "B2", 14, "/pəˈræləsis/", "Paralysis is the loss of the ability to move all or part of your body.", "sự tê liệt", "His paralysis meant that he had to use a wheelchair to get around.", "paralysis", []],
    "sr-b06-u09-14": ["pest", 0, "B1", 8, "/pest/", "A pest is an animal or insect that hurts plants or food.", "côn trùng gây hại", "Many farmers put up scarecrows to keep pests off of their corn.", "pests", ["keep pests"]],
    "sr-b06-u09-15": ["prevail", 1, "B2", 14, "/priˈveɪl/", "To prevail means to be accepted or very common.", "chiếm ưu thế", "Unfortunately, injustice still prevails in the country’s court system.", "prevails", []],
    "sr-b06-u09-16": ["respiration", 0, "B2", 14, "/ˌrespəˈreɪʃən/", "Respiration is the act of breathing.", "hô hấp", "Artificial respiration is the best thing to do if someone stops breathing.", "respiration", []],
    "sr-b06-u09-17": ["rupture", 1, "B2", 14, "/ˈrʌptʃər/", "To rupture means to tear or burst open.", "vỡ", "Sarah put too much water into the balloon, and it ruptured.", "ruptured", []],
    "sr-b06-u09-18": ["savage", 2, "C1", 14, "/ˈsævidʒ/", "If something or someone is savage, they are very violent or cruel.", "dã man", "Wild animals are very savage when defending their babies.", "savage", []],
    "sr-b06-u09-19": ["stun", 1, "B2", 14, "/stʌn/", "To stun someone means to make them unable to speak due to surprise or shock.", "làm sững sờ", "Tim fell off the swing and was too stunned to cry.", "stunned", ["stun to cry"]],
    "sr-b06-u09-20": ["susceptible", 2, "B2", 14, "/səˈseptəbəl/", "If one is susceptible to something like disease, they are easily harmed by it.", "dễ bị tổn thương", "Not eating enough vegetables makes you more susceptible to getting sick.", "susceptible", ["susceptible to getting"]],
    "sr-b06-u10-01": ["accumulate", 1, "B2", 14, "/əˈkjuːmjəleɪt/", "To accumulate something is to collect a lot of it over time.", "tích lũy", "The mail accumulated in their mailbox while they were on vacation.", "accumulated", []],
    "sr-b06-u10-02": ["aerial", 2, "C1", 14, "/ˈɛəriəl/", "When something is aerial, it relates to being in the air or flying.", "trên không", "The aerial photographer took pictures from the air balloon.", "aerial", ["aerial photographer"]],
