    "sr-b06-u10-04": ["avalanche", 0, "B2", 14, "/ˈævəlæntʃ/", "An avalanche is a large amount of snow, ice, and rock falling off a mountain.", "trận tuyết lở", "The avalanche destroyed the mountain village.", "avalanche", []],
    "sr-b06-u10-05": ["consistency", 0, "B2", 14, "/kənˈsistənsi/", "Consistency is the state of always behaving in the same way.", "tính nhất quán", "Her consistency in archery meant that our team had a chance to win.", "consistency", []],
    "sr-b06-u10-06": ["convection", 0, "C1", 14, "/kənˈvekʃən/", "Convection is the flow of hot air through gas or liquid.", "sự đối lưu", "The weather changed because of convection in the atmosphere.", "convection", []],
    "sr-b06-u10-07": ["discharge", 1, "B2", 14, "/ˈdistʃɑːrdʒ/", "To discharge someone is to allow them to leave from a place, usually a hospital.", "cho xuất viện, cho ra về", "I was discharged from the hospital after three days.", "discharged", ["discharge from the hospital"]],
    "sr-b06-u10-08": ["intact", 2, "B2", 14, "/inˈtækt/", "When something is intact, it is complete and not damaged.", "nguyên vẹn", "Despite being over ten years old, my father’s model ship is still intact.", "intact", []],
    "sr-b06-u10-09": ["mortal", 2, "B2", 14, "/ˈmɔːrtl/", "When a person is mortal, they cannot live forever.", "phải chết, hữu hạn", "All people are mortal.", "mortal", []],
    "sr-b06-u10-10": ["omen", 0, "B2", 14, "/ˈɑumən/", "An omen is a sign of what will happen in the future.", "điềm báo", "He thought that seeing a black cat in the street was an omen of bad luck.", "omen", []],
