    "sr-b06-u10-13": ["ranger", 0, "B1", 8, "/ˈreɪndʒər/", "A ranger is a person who protects the forest or parks.", "kiểm lâm", "Peter wanted to be a ranger because he liked spending time outside.", "ranger", []],
    "sr-b06-u10-14": ["rubble", 0, "B1", 8, "/ˈrʌbəl/", "Rubble is piles of broken stone and wood created after a building is destroyed.", "đống đổ nát", "There was rubble all over the city after the earthquake.", "rubble", []],
    "sr-b06-u10-15": ["seclude", 1, "B2", 14, "/siˈkluːd/", "To seclude someone means to keep them away from other people.", "tách biệt", "She was secluded on an island for over a year.", "secluded", ["seclude on an island"]],
    "sr-b06-u10-16": ["sideways", 3, "B1", 8, "/ˈsaɪdˌweɪz/", "shifting laterally to the left or right rather than straight ahead", "đi ngang", "Jim turned sideways in order to slow down and stop his snowboard.", "sideways", ["turned sideways"]],
    "sr-b06-u10-17": ["sob", 1, "B1", 8, "/sɒb/", "To sob is to cry loudly.", "nức nở", "I sobbed when my youngest daughter got married.", "sobbed", []],
