    "sr-b06-u11-02": ["authorize", 1, "B2", 14, "/ˈɔːθəraɪz/", "To authorize something means to give permission for it.", "ủy quyền", "The mayor authorized the construction of a new statue in the park.", "authorized", []],
    "sr-b06-u11-03": ["civilian", 0, "B2", 14, "/siˈviljən/", "A civilian is someone who is not in the military.", "thường dân", "It was Todd’s job to keep civilians from entering the army facility.", "civilians", ["keep civilians"]],
    "sr-b06-u11-04": ["commodity", 0, "B2", 14, "/kəˈmɒdəti/", "A commodity is something that can be bought or sold.", "hàng hóa", "Fran’s uncle made most of his money trading commodities.", "commodities", ["trading commodities"]],
    "sr-b06-u11-05": ["conquest", 0, "B2", 14, "/ˈkɒŋkwest/", "A conquest is an event by which one country takes over another country.", "cuộc chinh phạt", "After the conquest, the people of the small city had no freedom.", "conquest", []],
