    "sr-b06-u11-19": ["sentiment", 0, "B2", 14, "/ˈsentəmənt/", "A sentiment is an opinion based on your feelings.", "tình cảm", "Tess told everyone at the table her sentiments about eating meat.", "sentiments", ["table sentiments"]],
