    "sr-b06-u12-01": ["adorn", 1, "C1", 14, "/əˈdɔːrn/", "To adorn something means to make it more beautiful by decorating it.", "tô điểm", "Small glass beads adorned the vase.", "adorned", ["adorn the vase"]],
    "sr-b06-u12-02": ["bliss", 0, "C1", 14, "/blis/", "Bliss is a state of complete happiness.", "niềm hạnh phúc tột cùng", "Every time he sees his girlfriend, he feels a sense of bliss.", "bliss", []],
    "sr-b06-u12-03": ["butler", 0, "B2", 14, "/ˈbʌtlər/", "A butler is the most important male servant in a wealthy house.", "quản gia", "Whenever he needed something, he rang a bell, and the butler appeared.", "butler", []],
    "sr-b06-u12-04": ["cramp", 0, "B2", 14, "/kræmp/", "A cramp is a strong pain caused by a muscle after a lot of physical use.", "chuột rút", "After the marathon, Jenny got a terrible cramp in her calf muscle.", "cramp", ["terrible cramp"]],
