    "sr-b06-u12-09": ["filth", 0, "B1", 8, "/filθ/", "Filth is a large amount of dirt or dirty things that disgust you.", "sự bẩn thỉu", "There was tons of filth and trash on the shore of the river.", "filth", []],
    "sr-b06-u12-10": ["flaw", 0, "B2", 14, "/flɔː/", "A flaw is a mistake in something that causes it to be less effective or correct.", "khiếm khuyết", "We discovered a major flaw in the metal chain.", "flaw", ["major flaw"]],
    "sr-b06-u12-11": ["grin", 1, "B1", 8, "/grin/", "To grin means to smile broadly.", "cười toe toét", "That joke makes me grin every time I hear it.", "grin", []],
