    "sr-b06-u12-15": ["reckless", 2, "B2", 14, "/ˈreklis/", "When people are reckless, they act in an unsafe way.", "liều lĩnh", "The reckless driver posed a threat to everyone else on the road.", "reckless", ["reckless driver"]],
    "sr-b06-u12-16": ["slate", 0, "C1", 14, "/sleɪt/", "Slate is a dark grey rock that can easily be split into layers.", "đá phiến", "The roof of the church was made of slate.", "slate", []],
