    "sr-b06-u13-02": ["collaborate", 1, "B2", 14, "/kəˈlæbəreɪt/", "To collaborate means to work together on something.", "cộng tác", "When they collaborated, they managed to finish their chores early.", "collaborated", []],
    "sr-b06-u13-03": ["compile", 1, "B2", 14, "/kəmˈpaɪl/", "To compile things means to collect a variety of them into a group.", "biên soạn", "She compiled a list of people who she wanted to attend her birthday party.", "compiled", []],
