    "sr-b06-u13-11": ["intolerable", 2, "B2", 14, "/inˈtɒlərəbəl/", "If something is intolerable, then it is so bad that people cannot bear it.", "không thể chịu đựng được", "The weather was so intolerable that I had to put on my warmest clothes.", "intolerable", []],
    "sr-b06-u13-12": ["needy", 2, "B2", 14, "/ˈniːdi/", "If someone is needy, they are very poor.", "thiếu thốn", "After he lost his job, he became very needy.", "needy", []],
