    "sr-b06-u23-19": ["replicate", 1, "B2", 14, "/ˈrepləˌkeɪt/", "To replicate something is to do it in the exact same way as someone before.", "nhân rộng", "I would love to replicate my father’s achievements in school.", "replicate", []],
    "sr-b06-u23-20": ["wavy", 2, "B1", 8, "/ˈweɪvi/", "When something is wavy, it is not straight but has a series of curves.", "lượn sóng", "The child drew wavy lines all over the piece of paper.", "wavy", ["wavy lines"]],
    "sr-b06-u24-01": ["abide", 1, "C1", 14, "/əˈbaɪd/", "To abide by something, like a rule, means to obey it.", "tuân theo", "If you want to play the game with us, you must be willing to abide by our rules.", "abide", []],
    "sr-b06-u24-02": ["conversion", 0, "B2", 14, "/kənˈvɜːrʃən/", "Conversion is the act of changing something into a different state or form.", "chuyển đổi", "The city discussed the conversion of the parking lot into a skateboard park.", "conversion", ["discussed the conversion"]],
    "sr-b06-u24-03": ["cram", 1, "B2", 14, "/kræm/", "To cram things means to put them into a place that can barely contain them.", "nhồi nhét", "He crammed all of his shirts into the top drawer of the dresser.", "crammed", ["cram all"]],
    "sr-b06-u24-04": ["defer", 1, "C1", 14, "/diˈfɜːr/", "To defer means to arrange for an action to happen at a later time.", "trì hoãn", "The girl was very sleepy, so she chose to defer her bath until morning.", "defer", []],
    "sr-b06-u24-05": ["export", 1, "B1", 8, "/ˈekspɔːrt/", "To export products means to sell them to other countries.", "xuất khẩu", "The United States exports many cereals and grains.", "exports", []],
    "sr-b06-u24-06": ["fume", 0, "B2", 14, "/fjuːm/", "Fumes are unhealthy smoke and gases that are made by fires or chemicals.", "khói", "The engine put unpleasant, black fumes into the air.", "fumes", ["black fumes"]],
    "sr-b06-u24-07": ["habitual", 2, "B2", 14, "/həˈbitjuəl/", "When something is habitual, it is a behavior that a person usually does or has.", "theo thói quen thường xuyên", "The man was a habitual liar who was incapable of being honest with the police.", "habitual", ["habitual liar"]],
    "sr-b06-u24-08": ["justify", 1, "B1", 8, "/ˈdʒʌstəfaɪ/", "To justify something means to show or prove that it is necessary.", "biện minh", "The government tried to justify its decision to bring the country into a war.", "justify", []],
    "sr-b06-u24-09": ["output", 0, "B2", 14, "/ˈaʊtput/", "Output is the amount of something that a person or thing produces.", "đầu ra", "The boss hired more workers to increase the factory’s output of products.", "output", ["output of products"]],
    "sr-b06-u24-10": ["overpopulation", 0, "B2", 14, "/ˌoʊvərpɒpjuˈleɪʃən/", "Overpopulation is the state of having too many people in an area.", "quá tải dân số", "The organization is concerned with overpopulation of the world.", "overpopulation", ["overpopulation of the world"]],
    "sr-b06-u24-11": ["patent", 0, "B2", 14, "/ˈpætənt/", "A patent is a right to be the only person allowed to make or sell a new product.", "bằng sáng chế", "He quickly established a patent for his brilliant invention.", "patent", ["established a patent"]],
    "sr-b06-u24-12": ["penalize", 1, "B1", 8, "/ˈpiːnəlaɪz/", "To penalize someone means to punish him or her.", "trừng phạt", "The team was penalized when they broke the rules.", "penalized", []],
    "sr-b06-u24-13": ["petroleum", 0, "B1", 8, "/piˈtroʊliəm/", "Petroleum is a liquid natural resource from which many fuels are made.", "dầu mỏ", "The petroleum at that factory is used to make gasoline.", "petroleum", []],
    "sr-b06-u24-14": ["prototype", 0, "B2", 14, "/ˈproʊtətaɪp/", "A prototype is a new machine that is not ready to be made in large quantities.", "nguyên mẫu", "He introduced his prototype to the motorcycle company.", "prototype", ["introduced a prototype"]],
    "sr-b06-u24-15": ["scrap", 0, "B1", 8, "/skræp/", "A scrap of something is a small amount of it.", "mẩu nhỏ, chút ít", "Chris liked to use many scraps of paper when thinking up ideas.", "scraps", []],
    "sr-b06-u24-16": ["sector", 0, "B1", 8, "/ˈsektər/", "A sector is a part of a country’s economy in a specific type of industry.", "lĩnh vực", "We learned about just a few of the factories within the manufacturing sector.", "sector", ["manufacturing sector"]],
    "sr-b06-u24-17": ["subscribe", 1, "B1", 8, "/səbˈskraɪb/", "To subscribe to something is to agree or to concur with it.", "tán thành, đồng tình", "She subscribed to the view that musical education should be kept in schools.", "subscribed", ["subscribe to the view"]],
    "sr-b06-u24-18": ["subsist", 1, "B2", 14, "/səbˈsist/", "To subsist means to have the food, water, and money needed to stay alive.", "tồn tại", "Some people are forced to subsist on only a few dollars a month.", "subsist", []],
    "sr-b06-u24-19": ["suspend", 1, "B1", 8, "/səsˈpend/", "To suspend something means to delay or stop it from happening for a while.", "đình chỉ", "The oil company suspended production until it was sure the factory was safe.", "suspended", ["suspend production"]],
    "sr-b06-u24-20": ["synthesis", 0, "B2", 14, "/ˈsinθəsis/", "A synthesis is a combination of different ideas or styles.", "tổng hợp", "The band’s music was a synthesis of many different musical genres.", "synthesis", []],
    "sr-b06-u25-01": ["acrobat", 0, "C1", 14, "/ˈækrəbæt/", "An acrobat is a person who entertains people by doing amazing physical things.", "diễn viên nhào lộn", "There were acrobats at the circus that did impressive and complicated jumps.", "acrobats", []],
    "sr-b06-u25-02": ["advocacy", 0, "B2", 14, "/ˈædvəkəsi/", "Advocacy is the act of supporting or recommending something.", "sự vận động ủng hộ", "Janine’s strong advocacy for the event made people want to attend.", "advocacy", ["strong advocacy"]],
    "sr-b06-u25-03": ["communal", 2, "B2", 14, "/ˈkəmjuːnl/", "If something is communal, it involves a group of people.", "tập thể", "On the weekends, Theo and his son picked up trash in the communal park.", "communal", ["communal park"]],
    "sr-b06-u25-04": ["fluid", 2, "B1", 8, "/ˈfluːid/", "If something is fluid, it is smooth and moves gracefully.", "uyển chuyển, mượt mà", "Boris was a famous ballet dancer because people admired his fluid movements.", "fluid", ["fluid movements"]],
