    "sr-b06-u25-06": ["industrious", 2, "B2", 14, "/inˈdʌstriəs/", "If someone is industrious, they work hard.", "cần cù", "Dennis was very industrious, so he never had problems finding a job.", "industrious", []],
    "sr-b06-u25-07": ["inventive", 2, "B2", 14, "/inˈventiv/", "When someone is inventive, they are good at creating new things.", "có tính sáng tạo", "The inventive student built a robot to help her with her chores.", "inventive", ["inventive student"]],
    "sr-b06-u25-08": ["judicial", 2, "B2", 14, "/dʒuːˈdiʃəl/", "If something is judicial, it is related to judges or courts of law.", "tư pháp", "The laws changed the way the judicial system was structured.", "judicial", ["judicial system"]],
    "sr-b06-u25-09": ["Mandarin", 0, "B2", 14, "/ˈmændərin/", "Mandarin is one of the two main Chinese languages.", "tiếng Quan Thoại (Phổ thông)", "Although John’s parents both spoke Mandarin, he could only speak English.", "Mandarin", ["spoke mandarin"]],
