    "sr-b06-u25-13": ["rehearse", 1, "B1", 8, "/riˈhɜːrs/", "To rehearse means to practice and prepare for a performance in front of people.", "luyện tập", "Vick’s band rehearsed all week before their first show.", "rehearsed", ["rehearse all"]],
    "sr-b06-u25-14": ["scorn", 1, "C1", 14, "/ˈskɔːrn/", "To scorn someone means to behave without respect toward them.", "khinh miệt", "The criminal was scorned by everyone in the community.", "scorned", []],
