    "sr-b06-u25-18": ["veteran", 0, "B1", 8, "/ˈvetərən/", "A veteran is someone who has a lot of experience doing something.", "cựu chiến binh", "Hank was the team veteran and had played in more games than anyone else.", "veteran", ["team veteran"]],
    "sr-b06-u25-19": ["villain", 0, "C1", 14, "/ˈvilən/", "A villain is an evil person who breaks the law or hurts others.", "nhân vật phản diện", "The villain escaped with half of my family’s valuables.", "villain", []],
    "sr-b06-u25-20": ["vine", 0, "B1", 8, "/vaɪn/", "A vine is a plant that has long, twisting stems and climbs upward.", "dây leo", "The branches of the trees were covered with vines.", "vines", []],
