    "sr-b06-u26-18": ["tolerant", 2, "B1", 8, "/ˈtɒlərənt/", "When people are tolerant, they are approved of because they accept others.", "khoan dung", "The tolerant leader thought that everyone was equal regardless of race.", "tolerant", ["tolerant leader"]],
    "sr-b06-u26-19": ["vampire", 0, "B1", 8, "/ˈvæmpaɪər/", "A vampire is a fictional monster that sleeps in a coffin and sucks people’s blood.", "ma cà rồng", "The vampire snuck up on the woman and bit her in the neck.", "vampire", []],
