    "sr-b06-u27-01": ["analogy", 0, "B2", 14, "/əˈnælədʒi/", "An analogy is a connection made between things to show that they are similar.", "sự tương tự", "The doctor made an analogy between the human heart and a water pump.", "analogy", []],
    "sr-b06-u27-02": ["ancestry", 0, "B2", 14, "/ˈænsestri/", "A person's ancestry is the series of people from whom a person descended.", "tổ tiên", "We studied our ancestry and found out that we are related to royalty.", "ancestry", ["studied an ancestry"]],
    "sr-b06-u27-03": ["archer", 0, "C1", 14, "/ˈɑːrtʃər/", "An archer is a person who uses a bow and arrows.", "cung thủ", "The expert archer hit the target every time.", "archer", ["expert archer"]],
    "sr-b06-u27-04": ["conspiracy", 0, "B2", 14, "/kənˈspirəsi/", "A conspiracy is a secret plan made by a group of people to do something illegal.", "âm mưu", "Some people think that there was a conspiracy to kill American president John Kennedy.<br />", "conspiracy", []],
