    "sr-b06-u27-08": ["funnel", 0, "B1", 8, "/ˈfʌnl/", "A funnel is an object with a wide top and a narrow bottom for pouring liquids.", "cái phễu", "The worker used a funnel when he poured the oil into the engine.", "funnel", []],
    "sr-b06-u27-09": ["hereditary", 2, "B2", 14, "/hiˈredəˌteri/", "If something is hereditary, it is a trait passed onto children from their parents.", "di truyền", "The hereditary disease affected three generations of children.", "hereditary", ["hereditary disease"]],
    "sr-b06-u27-10": ["hymn", 0, "B2", 14, "/him/", "A hymn is a religious song that often praises a god.", "thánh ca", "The book was filled with hymns that the worshippers sang.", "hymns", []],
