    "sr-b06-u27-13": ["procession", 0, "B2", 14, "/prəˈseʃən/", "A procession is a group of people who walk or drive in a line during a public event.", "đám rước", "The procession all celebrated when they reached the end.", "procession", []],
    "sr-b06-u27-14": ["prophet", 0, "B2", 14, "/ˈprɒfit/", "A prophet is a person chosen by a god to give the god’s message to people.", "nhà tiên tri", "Harold believed that he was one of the prophets of his god.", "prophets", []],
